                // NO-OP
            }
            Ime::Preedit {
                value,
                window: _,
                cursor,
            } => {
                egui_input_message_writer.write(EguiInputEvent {
                    context,
                    event: egui::Event::Ime(egui::ImeEvent::Preedit {
                        text: value.clone(),
                        active_range_chars: cursor.map(|(start, end)| start..end),
                    }),
                });
