            Ime::Commit { value, window: _ } => {
                egui_input_message_writer.write(EguiInputEvent {
                    context,
                    event: egui::Event::Ime(egui::ImeEvent::Commit(value.clone())),
                });
            }
            Ime::Disabled { window: _ } => {
                // NO-OP
            }
        }
    }

